const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const rows = $input.all().map((i) => i.json).filter((r) => r.id);
if (!rows.length) return [];
return [{ json: { text: [
  `👻 <b>${rows.length} candidature(s) classée(s) « sans réponse »</b> après 2 relances :`,
  ...rows.map((r) => `• ${esc(r.title)}${r.company ? ' · ' + esc(r.company) : ''}`),
  '', 'Pas de panique, c\'est normal. Concentre-toi sur les nouvelles pépites : /offres',
].join('\n') } }];

const SYSTEM = "Tu rédiges des emails de relance de candidature en français : courts (70-110 mots), polis, confiants, jamais insistants.\nRappelle le poste et la date de candidature, réaffirme en une phrase la valeur ajoutée du candidat, propose un échange.\nSi c'est la 2e relance, sois encore plus bref et laisse une porte ouverte élégante.\nRéponds UNIQUEMENT avec un objet JSON : {\"subject\": \"...\", \"email\": \"...\"}";
return $input.all().filter((i) => i.json.application_id).map(({ json: a }) => {
  const days = Math.round((Date.now() - new Date(a.applied_at).getTime()) / 86400000);
  return {
    json: {
      ...a,
      days,
      llm_body: {
        temperature: 0.5,
        response_format: { type: 'json_object' },
        messages: [
          { role: 'system', content: SYSTEM },
          { role: 'user', content: [
            `Candidat : ${a.full_name || ''}`,
            `Poste : ${a.title} chez ${a.company || "l'entreprise"}`,
            `Candidature envoyée il y a ${days} jours. Relance n°${a.followup_count + 1}.`,
            `Résumé de l'offre : ${a.summary || ''}`,
            `Lettre envoyée (extrait) : ${(a.cover_letter || 'non disponible').slice(0, 1500)}`,
          ].join('\n') },
        ],
      },
    },
  };
});

// Retrouve l'élément d'origine d'un item grâce au suivi des « paired items » de n8n
const origin = (node, i) => { try { return $(node).itemMatching(i)?.json; } catch (e) { return $(node).all()[i]?.json; } };
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const parseLLM = (resp) => {
  if (resp?.error) throw new Error(resp.error.message || JSON.stringify(resp.error).slice(0, 300));
  const content = resp?.choices?.[0]?.message?.content;
  if (!content) throw new Error('Réponse vide du modèle IA');
  const clean = content.trim().replace(/^```(?:json)?\s*/i, '').replace(/```$/, '').trim();
  return JSON.parse(clean);
};

return $input.all().map((item, i) => {
  const a = origin('Préparer les relances', i);
  let subject = `Suivi de ma candidature – ${a.title}`;
  let email = '';
  try {
    const r = parseLLM(item.json);
    subject = r.subject || subject;
    email = r.email || '';
  } catch (e) {
    email = `(Rédaction automatique indisponible : ${e.message})`;
  }
  const text = [
    `⏰ <b>Relance n°${a.followup_count + 1} à envoyer</b>`,
    `<b>${esc(a.title)}</b>${a.company ? ' · ' + esc(a.company) : ''}`,
    `📨 Candidature envoyée il y a ${a.days} jours`,
    '',
    `<b>Objet :</b> ${esc(subject)}`,
    '',
    esc(email),
  ].join('\n');
  return { json: { application_id: a.application_id, job_id: a.job_id, url: a.url || 'https://francetravail.fr', text, content: `Objet : ${subject}\n\n${email}` } };
});

