WITH r AS (
  SELECT * FROM jsonb_to_recordset($1::jsonb) AS x(application_id int, job_id int, content text)
), docs AS (
  INSERT INTO documents (job_id, kind, content) SELECT job_id, 'followup', content FROM r RETURNING id
)
-- Si tu ne cliques sur rien, je te le rappelle dans 2 jours
UPDATE applications a SET next_followup_at = now() + interval '2 days'
FROM r WHERE a.id = r.application_id
RETURNING a.id;
